/* ==UserStyle==
@name         Vintage Pinterest Theme
@namespace    github.com/user/styles
@version      1.0.0
@description  Customizes Pinterest UI to reflect a warm vintage palette: soft beige, browns, and golden tones.
@match        *://*.pinterest.com/*
==/UserStyle== */

/* Background and General Layout */
body, html {
    background-color: #F4E1B0 !important; /* Soft Beige */
    color: #3B2F2F !important; /* Rich Brown */
}

/* Style Save and Follow buttons */
button, a[role="button"] {
    background-color: #D1A15F !important; /* Golden tone */
    color: #fff !important;
    border-radius: 15px !important;
    border: none !important;
    padding: 12px 18px !important;
    font-weight: bold !important;
    transition: background 0.3s ease;
}

button:hover, a[role="button"]:hover {
    background-color: #B6884B !important; /* Darker golden tone */
}

/* Pin Cards */
div[data-grid-item="true"] {
    background-color: #FFFFFF !important; /* Soft White for pins */
    border-radius: 12px !important;
    box-shadow: 0 0 8px rgba(0, 0, 0, 0.1) !important;
    border: 1px solid #E4D2A0 !important; /* Light beige border */
}

/* Clean up top navigation bar */
header {
    background-color: #3B2F2F !important; /* Rich Brown */
    border-bottom: 1px solid #B6884B !important; /* Golden accents */
}

/* Style search bar */
input[type="search"], input[data-test-id="search-box-input"] {
    background-color: #E4D2A0 !important; /* Light beige */
    color: #3B2F2F !important; /* Dark brown text */
    border: 1px solid #D1A15F !important; /* Golden border */
}

/* Modify links to match the vintage feel */
a {
    color: #D1A15F !important; /* Golden tone */
    text-decoration: none !important;
}

a:hover {
    color: #B6884B !important; /* Darker golden on hover */
}

/* Customize pin hover effects */
div[data-grid-item="true"]:hover {
    background-color: #F2E1C1 !important; /* Soft yellow on hover */
}

/* Remove "More Ideas" section */
div[data-test-id="related-pins"] {
    display: none !important;
}

/* Custom scrollbar */
::-webkit-scrollbar {
    width: 12px;
}
::-webkit-scrollbar-track {
    background: #F4E1B0;
}
::-webkit-scrollbar-thumb {
    background-color: #3B2F2F;
    border-radius: 10px;
    border: 2px solid #F4E1B0;
}
